-- Storefront edge node baseline schema.
-- All primary keys are UUIDv7 generated by the application (globally unique across the fleet).
-- Money is stored as NUMERIC + ISO-4217 currency code; never as floating point.

CREATE TABLE product (
    id                   UUID PRIMARY KEY,
    sku                  VARCHAR(64)   NOT NULL UNIQUE,
    name                 VARCHAR(200)  NOT NULL,
    unit_price           NUMERIC(19,4) NOT NULL CHECK (unit_price >= 0),
    currency             CHAR(3)       NOT NULL,
    tax_rate_percent     NUMERIC(7,4)  NOT NULL CHECK (tax_rate_percent BETWEEN 0 AND 100),
    requires_preparation BOOLEAN       NOT NULL DEFAULT FALSE,
    version              BIGINT        NOT NULL DEFAULT 0,
    updated_at           TIMESTAMPTZ   NOT NULL DEFAULT now()
);

-- Stock on hand per product. The CHECK is a last line of defence; the application never lets it trip
-- because it decrements with "WHERE on_hand >= :qty".
CREATE TABLE inventory (
    product_id UUID        PRIMARY KEY REFERENCES product (id),
    on_hand    INTEGER     NOT NULL CHECK (on_hand >= 0),
    version    BIGINT      NOT NULL DEFAULT 0,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Gap-free fiscal counters, one row per branch and business day. Updated inside the checkout
-- transaction, so a rollback returns the number.
CREATE TABLE fiscal_sequence (
    branch_code   VARCHAR(16) NOT NULL,
    business_date DATE        NOT NULL,
    last_value    BIGINT      NOT NULL CHECK (last_value > 0),
    PRIMARY KEY (branch_code, business_date)
);

CREATE TABLE customer_order (
    id            UUID          PRIMARY KEY,
    order_number  VARCHAR(64)   NOT NULL UNIQUE,
    branch_code   VARCHAR(16)   NOT NULL,
    business_date DATE          NOT NULL,
    sequence_no   BIGINT        NOT NULL,
    terminal_id   VARCHAR(64)   NOT NULL,
    status        VARCHAR(16)   NOT NULL,
    currency      CHAR(3)       NOT NULL,
    subtotal      NUMERIC(19,4) NOT NULL,
    tax_total     NUMERIC(19,4) NOT NULL,
    grand_total   NUMERIC(19,4) NOT NULL,
    placed_at     TIMESTAMPTZ   NOT NULL,
    origin_node   VARCHAR(64)   NOT NULL,
    version       BIGINT        NOT NULL DEFAULT 0,
    UNIQUE (branch_code, business_date, sequence_no)
);

CREATE TABLE order_line (
    id                   UUID          PRIMARY KEY,
    order_id             UUID          NOT NULL REFERENCES customer_order (id),
    line_no              INTEGER       NOT NULL,
    product_id           UUID          NOT NULL,
    sku                  VARCHAR(64)   NOT NULL,
    name                 VARCHAR(200)  NOT NULL,
    quantity             INTEGER       NOT NULL CHECK (quantity > 0),
    unit_price           NUMERIC(19,4) NOT NULL,
    tax_rate_percent     NUMERIC(7,4)  NOT NULL,
    line_tax             NUMERIC(19,4) NOT NULL,
    line_total           NUMERIC(19,4) NOT NULL,
    requires_preparation BOOLEAN       NOT NULL,
    UNIQUE (order_id, line_no)
);

-- One row per (terminal, client-generated key). The primary key makes concurrent duplicates block
-- on each other inside INSERT ... ON CONFLICT DO NOTHING.
CREATE TABLE idempotency_key (
    terminal_id         VARCHAR(64)  NOT NULL,
    idempotency_key     VARCHAR(128) NOT NULL,
    request_fingerprint CHAR(64)     NOT NULL,
    order_id            UUID         REFERENCES customer_order (id),
    created_at          TIMESTAMPTZ  NOT NULL,
    PRIMARY KEY (terminal_id, idempotency_key)
);

-- Transactional outbox. next_attempt_at doubles as a lease: a relay that claims a row pushes it into
-- the future, so a crash mid-delivery simply makes the row due again later (at-least-once).
CREATE TABLE outbox_event (
    id              UUID         PRIMARY KEY,
    destination     VARCHAR(32)  NOT NULL,
    event_type      VARCHAR(64)  NOT NULL,
    aggregate_id    UUID         NOT NULL,
    payload         JSONB        NOT NULL,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    next_attempt_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    attempts        INTEGER      NOT NULL DEFAULT 0,
    last_error      TEXT,
    published_at    TIMESTAMPTZ
);

CREATE INDEX outbox_event_due_idx
    ON outbox_event (destination, next_attempt_at)
    WHERE published_at IS NULL;

-- Kitchen Display System inbox. UNIQUE(order_id) makes the consumer idempotent under redelivery.
CREATE TABLE kitchen_ticket (
    id           UUID        PRIMARY KEY,
    order_id     UUID        NOT NULL UNIQUE,
    order_number VARCHAR(64) NOT NULL,
    terminal_id  VARCHAR(64) NOT NULL,
    items        JSONB       NOT NULL,
    status       VARCHAR(16) NOT NULL,
    received_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
